# Generated by manage.py generate_test_cases.
"""Request contracts for editing events through the shared calendar composer."""

from datetime import timedelta
from typing import Any

from bs4 import BeautifulSoup
from django.http import HttpResponse
from django.utils import timezone
from django.urls import reverse

from bloomerp.models.communication.calendar import CalendarEvent
from bloomerp.permissions.definition import RowPolicyRuleContent
from bloomerp.permissions.manager import PolicyManager
from bloomerp.tests.base import (
    BloomerpDetailViewTestCase,
    ExpectedResult,
    RequestScenario,
)
from bloomerp.tests.communication.inbox_calendar_fixtures import InboxCalendarFixtures


class TestCalendarEventUpdateView(InboxCalendarFixtures, BloomerpDetailViewTestCase):
    """Preserve event identity and enforce update permissions at the real detail route."""

    view_name = "update"
    model = CalendarEvent

    def extendedSetup(self) -> None:
        """Prepare existing timed/all-day events and one invited email address."""
        self.prepare_calendar()
        self.timed.organizing_inbox = self.source
        self.timed.save()
        self.all_day.organizing_inbox = self.source
        self.all_day.save()
        self.guest = self.timed.participants.create(email="guest@example.com")
        self.owner.email = "member@example.com"
        self.owner.save(update_fields=["email"])
        self.member = self.timed.participants.create(user=self.owner, email=self.owner.email)
        self.outsider.email = "invitee@example.com"
        self.outsider.save(update_fields=["email"])
        self.attendance = self.timed.participants.create(user=self.outsider, email=self.outsider.email)
        self.uid = self.timed.calendar_uid
        self.event_count = CalendarEvent.objects.count()

    def create_test_object(self) -> CalendarEvent:
        """Use the already placed timed event as the default detail route object."""
        return self.timed

    def event_data(self, **overrides: Any) -> dict[str, Any]:
        """Submit the same composer fields used by event creation without a create caller."""
        return {
            "inbox": str(self.source.pk), "title": "Updated meeting",
            "start_date": self.today.isoformat(), "end_date": self.today.isoformat(),
            "start_time": "14:00", "end_time": "15:00", "event_timezone": "Europe/London",
            "attendees": "guest@example.com, member@example.com", "attendee_users": f'["{self.owner.pk}"]',
            **overrides,
        }

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover prefilled fields, successful updates, invalid input, and denied edits."""
        return [
            RequestScenario(name="Linking an email guest reuses its existing participant", user=self.actor,
                prepare=self.prepare_email_guest_link, method="POST",
                data=self.event_data(attendees="member@example.com, invitee@example.com"),
                headers={"HX-Request": "true"},
                expected=ExpectedResult(status_code=204, response_validators=self.guest_linked)),
            RequestScenario(name="Removing a sent guest retains its cancellation identity", user=self.actor,
                prepare=self.mark_sent, method="POST", data=self.event_data(),
                headers={"HX-Request": "true"},
                expected=ExpectedResult(status_code=204, response_validators=self.removed_guest_retained)),
            RequestScenario(name="Staff event editors can add guests without participant read grants", user=self.owner,
                method="POST", prepare=self.prepare_external_guests,
                data=self.event_data(attendees="guest@example.com, member@example.com, invitee@example.com, new@example.com", attendee_users="[]"),
                headers={"HX-Request": "true"},
                expected=ExpectedResult(status_code=204, response_validators=self.guest_added)),
            RequestScenario(name="Calendar editor starts with the object sidebar collapsed", user=self.actor,
                expected=ExpectedResult(response_validators=self.sidebar_starts_collapsed)),
            RequestScenario(name="Invited attendees cannot open the event editor without edit grants", user=self.outsider,
                expected=ExpectedResult(status_code=403)),
            RequestScenario(name="The event editor does not accept attendance replies", user=self.outsider, method="POST",
                data={"response_status": "accepted", "sequence": 0},
                expected=ExpectedResult(status_code=403, response_validators=self.unchanged)),
            RequestScenario(name="Drawer GET reuses the prefilled composer", user=self.actor,
                headers={"HX-Request": "true", "HX-Target": "drawer-detail-pane-91"},
                expected=ExpectedResult(response_validators=self.prefilled)),
            RequestScenario(name="Timed update preserves event and participant identity", method="POST", user=self.actor,
                data=self.event_data(), headers={"HX-Request": "true"},
                expected=ExpectedResult(status_code=204, response_validators=self.updated)),
            RequestScenario(name="Invalid update leaves the event untouched", method="POST", user=self.actor,
                data=self.event_data(end_time="13:00"), headers={"HX-Request": "true"},
                expected=ExpectedResult(response_validators=self.unchanged)),
            RequestScenario(name="All-day updates reuse inclusive UI end dates", method="POST", user=self.actor,
                data=self.event_data(all_day="on", end_date=(self.today + timedelta(days=2)).isoformat()),
                headers={"HX-Request": "true"}, expected=ExpectedResult(status_code=204, response_validators=self.date_only_updated)),
            RequestScenario(name="Change permission works without add permission", user=self.owner,
                prepare=self.grant_change, expected=ExpectedResult(response_validators=self.prefilled_without_guests)),
            RequestScenario(name="Inbox access alone cannot edit an event", user=self.owner,
                expected=ExpectedResult(status_code=403)),
            RequestScenario(name="Denied POST cannot mutate an event", user=self.owner, method="POST", data=self.event_data(),
                expected=ExpectedResult(status_code=403, response_validators=self.unchanged)),
        ]

    def sidebar_starts_collapsed(self, response: HttpResponse) -> bool:
        """Keep the sidebar toggle and route the cancel button independently of composer submission."""
        soup = BeautifulSoup(response.content, "html.parser")
        panel = soup.select_one("#resizable-div-detail-aside")
        cancel = soup.select_one('button[hx-post="' + reverse("calendar_events_detail_cancel", kwargs={"pk": self.timed.pk}) + '"]')
        return (
            panel is not None
            and panel.get("data-force-close") == "true"
            and panel.get("data-toggle-shortcut") == "mod+shift+y"
            and cancel is not None and cancel.get("type") == "button"
        )

    def mark_sent(self, scenario: RequestScenario) -> None:
        """Mark an existing invitation as delivered without fabricating a connected sender."""
        CalendarEvent.objects.filter(pk=self.timed.pk).update(invitation_sent_at=timezone.now())

    def prepare_email_guest_link(self, scenario: RequestScenario) -> None:
        """Represent an internal user's invited mailbox using an existing email-only participant."""
        self.timed.participants.filter(pk=self.member.pk).delete()
        self.timed.participants.filter(pk=self.guest.pk).update(email=self.owner.email)

    def guest_linked(self, response: HttpResponse) -> bool:
        """Attach the selected user without changing the guest identity or inserting a duplicate email."""
        self.guest.refresh_from_db()
        return self.guest.user_id == self.owner.pk and self.timed.participants.count() == 2

    def removed_guest_retained(self, response: HttpResponse) -> bool:
        """Retain removed sent recipients for the next cancellation delivery instead of hard deletion."""
        self.attendance.refresh_from_db()
        return self.attendance.invitation_cancelled and self.timed.participants.filter(pk=self.attendance.pk).exists()

    def prepare_external_guests(self, scenario: RequestScenario) -> None:
        """Grant event editing while keeping participant permissions absent and user coupling out of scope."""
        self.grant_change(scenario)
        self.timed.participants.update(user=None)

    def guest_added(self, response: HttpResponse) -> bool:
        """Persist a new guest and retain every existing participant under a regular staff account."""
        return self.timed.participants.count() == 4 and self.timed.participants.filter(email="new@example.com").exists()

    def grant_change(self, scenario: RequestScenario) -> None:
        """Grant readable editable event fields without granting event or participant creation."""
        PolicyManager.create_policy(
            CalendarEvent, global_permissions=["view", "change"],
            field_permissions={"__all__": ["view", "change"]},
            row_permissions=[RowPolicyRuleContent(permissions=["view", "change"], conditions=[])],
        ).assign_user(self.owner)

    def prefilled(self, response: HttpResponse) -> bool:
        """Verify the shared controls load the existing event and invited address in the drawer."""
        form = response.context["form"]
        return (
            form.initial["title"] == self.timed.title
            and form.initial["inbox"] == self.source.pk
            and "guest@example.com" in form.initial["attendees"]
            and "member@example.com" in form.initial["attendees"]
            and response.context["form_url"] == self.timed.get_absolute_url()
            and b'calendar-event-editor' in response.content
            and b'calendar-availability' in response.content
            and b'id="object-crud-container-buttons"' in response.content
            and b'bloomerp-close-modal="create-object-modal"' not in response.content
        )

    def prefilled_without_guests(self, response: HttpResponse) -> bool:
        """Keep unreadable linked users out of the update form without requiring add access."""
        return response.context["form"].initial["title"] == "Placed timed meeting" and "attendees" not in response.context["form"].fields

    def updated(self, response: HttpResponse) -> bool:
        """Confirm an update, rather than a duplicate creation or participant replacement."""
        self.timed.refresh_from_db()
        return (
            response["HX-Refresh"] == "true" and self.timed.title == "Updated meeting"
            and self.timed.calendar_uid == self.uid and CalendarEvent.objects.count() == self.event_count
            and self.timed.participants.filter(pk=self.guest.pk).exists()
            and self.timed.participants.filter(pk=self.member.pk).exists()
            and self.timed.event_timezone == "Europe/London"
            and self.timed.updated_by_id == self.actor.pk
        )

    def unchanged(self, response: HttpResponse) -> bool:
        """Reject mutations while preserving the existing event and participant."""
        self.timed.refresh_from_db()
        return self.timed.title == "Placed timed meeting" and CalendarEvent.objects.count() == self.event_count

    def date_only_updated(self, response: HttpResponse) -> bool:
        """Store an exclusive all-day end while clearing the previous timed representation."""
        self.timed.refresh_from_db()
        return (
            self.timed.all_day and self.timed.start is None and self.timed.end is None
            and self.timed.start_date == self.today
            and self.timed.end_date == self.today + timedelta(days=3)
            and self.timed.calendar_uid == self.uid
        )
